INSERT INTO `achievements` (`id`,`name`,`description`,`icon_id`,`points`,`has_reward`,`client_flag`,`version`,`reset_on_version_change`,`enabled`) VALUES
(500010100,'Graduate of Crescent Reach (1-20)','This achievement is gained upon completing all the following quest-lines in Crescent Reach:',3395,10,1,0,0,1,1),
(500010200,'Welcome to Crescent Reach (1+)','Emissary Tinnvin, Innkeeper Fathus, and Council Aide Mystrana would like you to familiarize yourself with the city:',504,4,0,0,0,1,1),
(500010300,'Ready for Combat (1-5)','Champion Utenka and Initiate Dakkan have several jobs for you to complete:',580,4,0,0,0,1,1),
(500010400,'Important Errands (6-10)','Baker Shivra and Jinkin are in need of help with some important errands:',580,5,1,0,0,1,1),
(500010500,'Making a Name for Yourself (11-15)','Council Aide Shay, Skinner Bezuth and Vunder the Dark are seeking the help of adventurers:',580,5,1,0,0,1,1),
(500010600,'Becoming a Hero (16-20)','Akins, Farmer Joen, and Farmer Lize are in need of help:',580,6,1,0,0,1,1),
(500010700,'The Council of Six (Crescent 1+)','Work with Council Aide Mystrana to introduce and prove yourself to the Council of Six:',866,7,0,0,0,1,1),
(500010800,'Love in the Air (Crescent 1+)','Speak with Guard Captain Minka to unravel this tale of unrequited love(s):',3795,4,0,0,0,1,1),
(500010900,'Boawb''s Jealousy (Crescent 1+)','Speak with Disgruntled Boawb about his ''interesting'' ideas about the council:',592,2,1,0,0,1,1)
