-- RoF2 zone content: Crescent Reach (nightstalker6669/eqemu-rof2-achievements reconstruction).
-- Applied verbatim: catalogue, native task dependencies, quests, making-a-name, becoming-hero,
-- baker quests. Stock-row deltas reviewed 2026-11-01: task 6020 created then made
-- non-repeatable (retail-accurate), items 84202/84204 price=0 (no-op, already 0),
-- merchantlist 394135 guarded inserts. Fail-closed guards abort on mismatch.
-- Curated nine Crescent Reach achievement definitions and dependencies only.
-- No client resource files or character state.
SET NAMES utf8mb4;
START TRANSACTION;
ON DUPLICATE KEY UPDATE `id`=VALUES(`id`),`parent_id`=VALUES(`parent_id`),`sequence`=VALUES(`sequence`),`name`=VALUES(`name`),`description`=VALUES(`description`),`icon`=VALUES(`icon`);
ON DUPLICATE KEY UPDATE `id`=VALUES(`id`),`name`=VALUES(`name`),`description`=VALUES(`description`),`icon_id`=VALUES(`icon_id`),`points`=VALUES(`points`),`has_reward`=VALUES(`has_reward`),`client_flag`=VALUES(`client_flag`),`version`=VALUES(`version`),`reset_on_version_change`=VALUES(`reset_on_version_change`),`enabled`=VALUES(`enabled`);
ON DUPLICATE KEY UPDATE `achievement_id`=VALUES(`achievement_id`),`component_type`=VALUES(`component_type`),`sequence`=VALUES(`sequence`),`component_id`=VALUES(`component_id`),`name`=VALUES(`name`),`description`=VALUES(`description`);
ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`sequence`=VALUES(`sequence`),`achievement_id`=VALUES(`achievement_id`),`display_text`=VALUES(`display_text`);
DELETE FROM achievement_criteria WHERE achievement_id IN(500010100,500010200,500010300,500010400,500010500,500010600,500010700,500010800,500010900);
ON DUPLICATE KEY UPDATE `achievement_id`=VALUES(`achievement_id`),`component_type`=VALUES(`component_type`),`component_sequence`=VALUES(`component_sequence`),`component_id`=VALUES(`component_id`),`event_type`=VALUES(`event_type`),`progress_mode`=VALUES(`progress_mode`),`behavior`=VALUES(`behavior`),`target_id`=VALUES(`target_id`),`target_id2`=VALUES(`target_id2`),`target_value`=VALUES(`target_value`),`required_count`=VALUES(`required_count`),`enabled`=VALUES(`enabled`);
ON DUPLICATE KEY UPDATE `reward_set_id`=VALUES(`reward_set_id`),`title`=VALUES(`title`),`enabled`=VALUES(`enabled`);
ON DUPLICATE KEY UPDATE `source_type`=VALUES(`source_type`),`source_id`=VALUES(`source_id`),`reward_set_id`=VALUES(`reward_set_id`),`enabled`=VALUES(`enabled`);
ON DUPLICATE KEY UPDATE `reward_set_id`=VALUES(`reward_set_id`),`option_id`=VALUES(`option_id`),`sequence`=VALUES(`sequence`),`label`=VALUES(`label`),`common_to_all`=VALUES(`common_to_all`),`flags`=VALUES(`flags`),`enabled`=VALUES(`enabled`),`class_mask`=VALUES(`class_mask`);
ON DUPLICATE KEY UPDATE `reward_id`=VALUES(`reward_id`),`reward_type`=VALUES(`reward_type`),`reward_data_id`=VALUES(`reward_data_id`),`amount`=VALUES(`amount`),`description`=VALUES(`description`),`enabled`=VALUES(`enabled`);
ON DUPLICATE KEY UPDATE `reward_set_id`=VALUES(`reward_set_id`),`option_id`=VALUES(`option_id`),`sequence`=VALUES(`sequence`),`reward_id`=VALUES(`reward_id`);
COMMIT;
-- Native PEQ task dependencies for the nine scoped Crescent achievements.
